# Generated by build.py from recipe.yml for recipe surl-share-one-account-file. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site', 'extra' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'extra/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'users.txt'), "# test accounts, one user:password a line`nalice:s3cret`nbob:b0bpass`n")
[IO.File]::WriteAllText((Join-Path $PWD 'extra-users.txt'), "bob:b0bpass`n")
[IO.File]::WriteAllText((Join-Path $PWD 'bad-users.txt'), "alice`n")
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"'
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--cert', 'server.pem', '--key', 'server.key', '--user-file', 'users.txt', 'https://127.0.0.1:8080/', 'ftps://127.0.0.1:8081/', 'imaps://127.0.0.1:8082/', 'mqtts://127.0.0.1:8083/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s --cacert server.pem -u alice:s3cret https://127.0.0.1:8080/hello.txt --next -s --cacert server.pem -u alice:s3cret ftps://127.0.0.1:8081/hello.txt --next -s --cacert server.pem -u alice:s3cret -X "STATUS INBOX (MESSAGES)" imaps://127.0.0.1:8082/ --next -s --cacert server.pem -u alice:s3cret -d on mqtts://127.0.0.1:8083/t/lamp } finally { Stop-Process $server0 }
